package com.commercecore.payment; import com.commercecore.order.CustomerOrder;import com.commercecore.user.UserAccount;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="payments") public class Payment{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="order_id",nullable=false)CustomerOrder order;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="customer_id",nullable=false)UserAccount customer;@Enumerated(EnumType.STRING)@Column(name="payment_method",nullable=false)PaymentMethod paymentMethod;@Enumerated(EnumType.STRING)@Column(nullable=false)PaymentStatus status;@Column(nullable=false,precision=19,scale=2)BigDecimal amount;@Column(name="currency_code",nullable=false,length=3)String currencyCode="USD";@Column(name="idempotency_key",nullable=false,length=160)String idempotencyKey;@Column(name="request_fingerprint",nullable=false,length=64)String requestFingerprint;@Column(name="provider_name",nullable=false)String providerName="SANDBOX";@Column(name="provider_payment_reference")String providerPaymentReference;@Column(name="provider_idempotency_key",nullable=false)String providerIdempotencyKey;@Column(name="failure_code")String failureCode;@Column(name="failure_message")String failureMessage;@Column(name="retryable_failure",nullable=false)boolean retryableFailure;@Column(name="reconciliation_required",nullable=false)boolean reconciliationRequired;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;@Column(name="updated_at",nullable=false)Instant updatedAt;@Version long version;protected Payment(){}public Payment(CustomerOrder o,UserAccount c,PaymentMethod m,BigDecimal a,String k,String f,String pk){order=o;customer=c;paymentMethod=m;amount=a.setScale(2,RoundingMode.HALF_UP);idempotencyKey=k;requestFingerprint=f;providerIdempotencyKey=pk;status=PaymentStatus.PENDING;}public void authorized(String r){if(status!=PaymentStatus.PENDING)throw new IllegalStateException();status=PaymentStatus.AUTHORIZED;providerPaymentReference=r;}public void paid(String r){if(status!=PaymentStatus.AUTHORIZED)throw new IllegalStateException();status=PaymentStatus.PAID;providerPaymentReference=r;}public void recoverPaid(String r){if(status!=PaymentStatus.PENDING&&status!=PaymentStatus.FAILED&&status!=PaymentStatus.AUTHORIZED)throw new IllegalStateException();status=PaymentStatus.PAID;providerPaymentReference=r;reconciliationRequired=false;}public void failed(String c,String m,boolean r){if(status!=PaymentStatus.PENDING&&status!=PaymentStatus.AUTHORIZED)throw new IllegalStateException();status=PaymentStatus.FAILED;failureCode=c;failureMessage=m;retryableFailure=r;}public void refunded(boolean partial){if(status!=PaymentStatus.PAID&&status!=PaymentStatus.PARTIALLY_REFUNDED)throw new IllegalStateException();status=partial?PaymentStatus.PARTIALLY_REFUNDED:PaymentStatus.REFUNDED;}public void reconciliation(boolean v){reconciliationRequired=v;}@PrePersist void pre(){createdAt=updatedAt=Instant.now();}@PreUpdate void upd(){updatedAt=Instant.now();}public UUID getId(){return id;}public CustomerOrder getOrder(){return order;}public UserAccount getCustomer(){return customer;}public PaymentMethod getPaymentMethod(){return paymentMethod;}public PaymentStatus getStatus(){return status;}public BigDecimal getAmount(){return amount;}public String getIdempotencyKey(){return idempotencyKey;}public String getRequestFingerprint(){return requestFingerprint;}public String getProviderPaymentReference(){return providerPaymentReference;}public String getProviderIdempotencyKey(){return providerIdempotencyKey;}public String getCurrencyCode(){return currencyCode;}public boolean isReconciliationRequired(){return reconciliationRequired;}public boolean isRetryableFailure(){return retryableFailure;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
